assignments.referenceSolution:
Exceptions carry behaviour (`retryable`) and data (`retry_after`, `status`) instead of encoding them in strings, and `from_status` keeps the cause chain so logs show the real origin. Logging is configured once with `dictConfig`; a filter copies the `ContextVar` value onto each record and a formatter renders JSON, so request context never has to be passed through function parameters. Because asyncio gives each task its own copy of the context, concurrent requests keep separate ids.

**`errors.py`**

```python
from __future__ import annotations


class GatewayError(Exception):
    """Base class for every error this service raises on purpose."""

    retryable: bool = False


class UpstreamError(GatewayError):
    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


class UpstreamTimeout(UpstreamError):
    retryable = True


class UpstreamUnavailable(UpstreamError):
    retryable = True


class RateLimited(UpstreamError):
    retryable = True

    def __init__(self, message: str, *, retry_after: float | None = None) -> None:
        super().__init__(message, status=429)
        self.retry_after = retry_after


class BadRequest(UpstreamError):
    retryable = False


def from_status(
    status: int, *, retry_after: float | None = None, cause: BaseException | None = None
) -> UpstreamError:
    """Translate an HTTP status into a domain error (optionally chaining a cause)."""
    err: UpstreamError
    if status == 429:
        err = RateLimited("rate limited", retry_after=retry_after)
    elif status in (408, 504):
        err = UpstreamTimeout(f"upstream timeout ({status})", status=status)
    elif status >= 500:
        err = UpstreamUnavailable(f"upstream unavailable ({status})", status=status)
    elif status >= 400:
        err = BadRequest(f"bad request ({status})", status=status)
    else:
        raise ValueError(f"not an error status: {status}")
    err.__cause__ = cause
    return err
```

**`jsonlog.py`**

```python
from __future__ import annotations

import contextvars
import json
import logging
import logging.config
from collections.abc import Iterator
from contextlib import contextmanager
from typing import IO, Any

request_id: contextvars.ContextVar[str] = contextvars.ContextVar("request_id", default="-")

_RESERVED = set(vars(logging.makeLogRecord({}))) | {"message", "asctime", "request_id"}


@contextmanager
def bind_request_id(value: str) -> Iterator[None]:
    token = request_id.set(value)
    try:
        yield
    finally:
        request_id.reset(token)


class ContextFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:
        record.request_id = request_id.get()
        return True


class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "level": record.levelname,
            "logger": record.name,
            "msg": record.getMessage(),
            "request_id": getattr(record, "request_id", "-"),
        }
        for key, value in vars(record).items():
            if key not in _RESERVED:
                payload[key] = value
        if record.exc_info and record.exc_info[0] is not None:
            payload["exc_type"] = record.exc_info[0].__name__
            payload["exc"] = str(record.exc_info[1])
            cause = record.exc_info[1].__cause__ if record.exc_info[1] else None
            if cause is not None:
                payload["cause"] = f"{type(cause).__name__}: {cause}"
        return json.dumps(payload, sort_keys=True, default=str)


def configure(stream: IO[str], level: str = "INFO") -> None:
    logging.config.dictConfig(
        {
            "version": 1,
            "disable_existing_loggers": False,
            "filters": {"ctx": {"()": ContextFilter}},
            "formatters": {"json": {"()": JsonFormatter}},
            "handlers": {
                "app": {
                    "class": "logging.StreamHandler",
                    "stream": stream,
                    "formatter": "json",
                    "filters": ["ctx"],
                }
            },
            "loggers": {"gateway": {"level": level, "handlers": ["app"], "propagate": False}},
        }
    )
