**`test_errors_logging.py`**

```python
import asyncio
import io
import json
import logging

import pytest

import jsonlog
from errors import (
    BadRequest, GatewayError, RateLimited, UpstreamTimeout, UpstreamUnavailable, from_status,
)


@pytest.mark.parametrize(
    ("status", "cls", "retryable"),
    [
        pytest.param(429, RateLimited, True, id="429"),
        pytest.param(504, UpstreamTimeout, True, id="504"),
        pytest.param(503, UpstreamUnavailable, True, id="503"),
        pytest.param(400, BadRequest, False, id="400"),
        pytest.param(404, BadRequest, False, id="404"),
    ],
)
def test_status_translation(status: int, cls: type[GatewayError], retryable: bool) -> None:
    err = from_status(status)
    assert type(err) is cls
    assert err.retryable is retryable
    assert isinstance(err, GatewayError)


def test_retry_after_and_cause_are_kept() -> None:
    original = TimeoutError("read timed out")
    err = from_status(429, retry_after=7.5, cause=original)
    assert isinstance(err, RateLimited)
    assert err.retry_after == 7.5
    assert err.__cause__ is original


def test_non_error_status_rejected() -> None:
    with pytest.raises(ValueError, match="not an error status"):
        from_status(200)


@pytest.fixture
def stream() -> io.StringIO:
    buf = io.StringIO()
    jsonlog.configure(buf)
    return buf


def lines(stream: io.StringIO) -> list[dict[str, object]]:
    return [json.loads(line) for line in stream.getvalue().splitlines()]


def test_json_line_has_context_and_extras(stream: io.StringIO) -> None:
    log = logging.getLogger("gateway.billing")
    with jsonlog.bind_request_id("req-1"):
        log.info("charged %s", "acme", extra={"tokens": 1200})
    log.debug("below INFO: dropped")
    assert lines(stream) == [
        {"level": "INFO", "logger": "gateway.billing", "msg": "charged acme",
         "request_id": "req-1", "tokens": 1200}
    ]


def test_request_id_resets_after_context(stream: io.StringIO) -> None:
    log = logging.getLogger("gateway.x")
    with jsonlog.bind_request_id("req-1"):
        pass
    log.info("after")
    assert lines(stream)[0]["request_id"] == "-"


def test_exception_logging_includes_type_and_cause(stream: io.StringIO) -> None:
    log = logging.getLogger("gateway.vendor")
    try:
        try:
            raise TimeoutError("read timed out")
        except TimeoutError as exc:
            raise from_status(504, cause=exc)
    except UpstreamTimeout:
        log.exception("vendor call failed")
    record = lines(stream)[0]
    assert record["level"] == "ERROR"
    assert record["exc_type"] == "UpstreamTimeout"
    assert record["cause"] == "TimeoutError: read timed out"


@pytest.mark.asyncio
async def test_concurrent_tasks_do_not_share_request_ids(stream: io.StringIO) -> None:
    log = logging.getLogger("gateway.async")

    async def handle(n: int) -> None:
        with jsonlog.bind_request_id(f"req-{n}"):
            await asyncio.sleep(0)
            log.info("working", extra={"n": n})

    await asyncio.gather(*(handle(n) for n in range(5)))
    seen = {(rec["n"], rec["request_id"]) for rec in lines(stream)}
    assert seen == {(n, f"req-{n}") for n in range(5)}
```

Run `pytest -q` (needs `pytest` and `pytest-asyncio`).
